import re

def run(spec: str, verilog: str, ports: list[dict]) -> dict:
    """
    Detects output ports that are assigned inside an always block but are not declared as logic/reg.
    Returns findings if any such port is found.
    """
    # Extract output port names
    output_names = {p["name"] for p in ports if p["direction"] == "output"}

    # Find all always block bodies (simplistic: from always @* or always @(...) to next 'end' at same indent)
    # We'll just look for assignments to outputs inside any always block.
    # Remove comments and strings to avoid false positives.
    lines = verilog.splitlines()
    in_always = False
    brace_depth = 0
    assigned_in_always = set()
    declared_type = {}  # net type for each output (wire, logic, reg, etc.)

    # First pass: collect declarations
    decl_re = re.compile(r'^\s*(?:(?:logic|reg|wire)\s+)\[?[^\]]*\]?\s+([a-zA-Z_][a-zA-Z0-9_]*)')
    for line in lines:
        stripped = line.strip('{}; ')
        if stripped.startswith('//'):
            continue
        m = decl_re.search(line)
        if m:
            name = m.group(1)
            if name in output_names:
                # Determine type keyword
                if 'logic' in line:
                    declared_type[name] = 'logic'
                elif 'reg' in line:
                    declared_type[name] = 'reg'
                else:
                    declared_type[name] = 'wire'

    # Second pass: detect assignments inside always blocks
    for line in lines:
        if 'always' in line and ('@' in line):
            in_always = True
            brace_depth = line.count('(') - line.count(')')
            continue
        if in_always:
            brace_depth += line.count('(') - line.count(')')
            brace_depth += line.count('{') - line.count('}')
            # Look for blocking or nonblocking assignment to an output
            assign_matches = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*[<=]=', line)
            for name in assign_matches:
                if name in output_names:
                    assigned_in_always.add(name)
            if brace_depth == 0 and '}' in line:
                in_always = False

    findings = []
    for name in assigned_in_always:
        if declared_type.get(name) not in ('logic', 'reg'):
            findings.append(f"Output '{name}' assigned in always block but declared as {declared_type.get(name, 'wire')}; should be logic or reg.")
    return {"fired": bool(findings), "findings": findings}
